// === Tab: Projet_follower_particule ===
// let Alex Gattefossé (a.k.a. Dakumisu)

// reset function setup() : let int rdm = int(random(3000, 5000));
let puissance = 0.3;
let vitesse = 15;
let intensite = 1;
Follower [] follower = new Array(rdm);
let createText = new Text();

let offsetX = 0;
let offsetY = 0;
let easing = 0.15;

let noisePower = int(random(5, 10));

function setup() {
  // fullScreen(P2D, SPAN);
  createCanvas(1000, 1000);
  background(20);
  for (i = 0; i < follower.length; i++) {
    follower[i] = new Follower();
  }
  createText.textSetup();
}

function draw() {
  background(20);

  fill(220, 50);
  rect(0, 0, width, 125);

  for ( i =0; i < follower.length; i++) {
    follower[i].update(); 
    follower[i].render();
  }

  stroke(255, 50);
  strokeWeight(50);
  let dx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - offsetX;
  offsetX += dx * easing;
  let dy = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - offsetY;
  offsetY += dy * easing; 
  point(offsetX, offsetY);
  noStroke();

  createText.varText("I", 10, 25, 76, 201, 241);
  createText.varText("P", 10, 50, 76, 201, 241);
  createText.varText("S", 10, 75, 76, 201, 241);
  createText.varText("ntensity : ", 16, 25, 255, 255, 255);
  createText.varText("ower : ", 19, 50, 255, 255, 255);
  createText.varText("peed : ", 19, 75, 255, 255, 255);
  createText.varText("Options : ", 10, 100, 255, 255, 255);

  createText.varText("A", 200, 100, 255, 255, 255);
  createText.varText("Z", 215, 100, 255, 255, 255);
  createText.varText("I", 209, 118, 76, 201, 241);

  createText.varText("Q", 245, 100, 255, 255, 255);
  createText.varText("S", 260, 100, 255, 255, 255);
  createText.varText("D", 275, 100, 255, 255, 255);
  createText.varText("F", 290, 100, 255, 255, 255);
  createText.varText("G", 305, 100, 255, 255, 255);
  createText.varText("+", 320, 100, 255, 255, 255);
  createText.varText("-", 335, 100, 255, 255, 255);
  createText.varText("P", 290, 118, 76, 201, 241);


  createText.varText("V", 365, 100, 255, 255, 255);
  createText.varText("V", 365, 118, 76, 201, 241);

  createText.varText("Left click", 420, 100, 255, 255, 255);
  createText.varText("Right click", 520, 100, 255, 255, 255);


  createText.varNumber(intensite, 90, 25, 255, 255, 255);
  createText.varNumber(puissance, 100, 50, 255, 255, 255);
  createText.varNumber(vitesse, 80, 75, 255, 255, 255);


  if (keyPressed && key == '+') {
    createText.varText("+", 320, 100, 247, 37, 133);
  } else if (keyPressed && key == '-') {
    createText.varText("-", 335, 100, 247, 37, 133);
  } else if (key == 'q' || key == 'Q') {
    createText.varText("Q", 245, 100, 247, 37, 133);
  } else if (key == 's' || key == 'S') {
    createText.varText("S", 260, 100, 247, 37, 133);
  } else if (key == 'd' || key == 'D') {
    createText.varText("D", 275, 100, 247, 37, 133);
  } else if (key == 'f' || key == 'F') {
    createText.varText("F", 290, 100, 247, 37, 133);
  } else if (key == 'g' || key == 'G') {
    createText.varText("G", 305, 100, 247, 37, 133);
  } else if (keyPressed && key == 'v' || key == 'V') {
    createText.varText("V", 365, 100, 247, 37, 133);
  } else if (keyPressed && key == 'a' || key == 'A') {
    createText.varText("A", 200, 100, 247, 37, 133);
  } else if (keyPressed && key == 'z' || key == 'Z') {
    createText.varText("Z", 215, 100, 247, 37, 133);
  }

  if (mousePressed && mouseButton == LEFT) {
    createText.varText("Left click", 420, 100, 247, 37, 133);
  } else if (mousePressed && mouseButton == RIGHT) {
    createText.varText("Right click", 520, 100, 76, 201, 241);
  }

  noise();

  if (keyPressed && key == 'r') {
    setup();
  }
}

function noise() {
  strokeWeight(1);
  for (i = -width/noisePower; i < width/noisePower - 1; i += 5) {
    for (j = -height/noisePower; j < height/noisePower   - 1; j += 5) {
      fill(random(100, 255), random(20, 40));
      rect(random(0, width), random(0, height), random(1, 2), random(1, 2));
    }
  }
  for (i = 0; i < 15; i++) {
    fill(random(0, 255), 255);
    rect(random(0, width), random(0, height), 2, 2);
  }
}

// === Tab: particules ===
class Follower {
  loc, vel, acc; 

  constructor() {
    loc = new PVector(random(width), random(height));
    vel= new PVector();
    acc= new PVector();
  }

  function render() {
    if (mousePressed && mouseButton == LEFT) {
      fill(247, 37, 133, 50);
    } else if (mousePressed && mouseButton == RIGHT) {
      fill(76, 201, 241, 50);
    } else {
      fill(255, 255, 255, 50);
    }
    noStroke();
    ellipse(loc.x, loc.y, 5, 5);
  }

  function update() {
    acc = new PVector(offsetX-loc.x, offsetY -loc.y); 

    if (keyPressed && key == '+') {
      puissance += 0.00001;
    } else if (keyPressed && key == '-') {
      puissance -= 0.00001;
    } else if (keyPressed && key == 'q' || key == 'Q') {
      puissance = 0.3;
    } else if (keyPressed && key == 's' || key == 'S') {
      puissance = 0.8;
    } else if (keyPressed && key == 'd' || key == 'D') {
      puissance = 1.1;
    } else if (keyPressed && key == 'f' || key == 'F') {
      puissance = 5;
    } else if (keyPressed && key == 'g' || key == 'G') {
      puissance = 10;
    }

    acc.limit(puissance);

    vel.add(acc);

    if (keyPressed && key == 'v' || key == 'V') {
      vitesse = 100;
    } else {
      vitesse = 15;
    }

    vel.limit(vitesse);

    loc.add(vel);


    if (keyPressed && key == 'a' || key == 'A') {
      intensite = 2;
    } else if (keyPressed && key == 'z' || key == 'Z') {
      intensite = 3;
    } else {
      intensite = 1;
    }

    vel.mult(intensite);
  }
}

// === Tab: text ===
class Text {
  font;

  function textSetup() {
    font = loadFont("https://openprocessing.org/sketch/1173476/files/BookmanOldStyle-Bold-15.vlw");
  }

  function varText(currentText, x, y, coloR, coloV, coloB) {
    fill(coloR, coloV, coloB);
    textFont(font);

    text(currentText, x, y);
  }

  function varNumber(currentText, x, y, coloR, coloV, coloB) {
    fill(coloR, coloV, coloB);
    textFont(font);

    text(currentText, x, y);
  }
}

